//! Line-wrap estimate for the settings pages in the Deck's UI font. Gaming Mode falls back to DejaVu Sans (fontconfig) for Latin and
//! Cyrillic, so widths come from its real advance table (`dejavu_advances.in`, generated by tools/extract-assets/dejavu_advances.py)
//! instead of an average per-letter width. Verified against the owner's stock captures: 24 px / 18 px text matches measured line widths
//! within 1 %. The estimate drives both the card height and the actual line breaks (`wrap_text` inserts `\n` and the renderer does not
//! re-wrap), so the picture and the geometry agree even where the PC test font is narrower than DejaVu.

const ADVANCES: &[(u32, u16)] = include!("dejavu_advances.in");
const UNITS_PER_EM: f32 = 2048.;
/// advance of a character missing from the table (DejaVu average, em)
const FALLBACK_EM: f32 = 0.6;

fn advance_em(c: char) -> f32 {
    match ADVANCES.binary_search_by_key(&(c as u32), |e| e.0) { Ok(i) => ADVANCES[i].1 as f32 / UNITS_PER_EM, Err(_) => FALLBACK_EM }
}

/// Advance width of `s` at `px` font size.
pub fn text_width(s: &str, px: f32) -> f32 { s.chars().map(advance_em).sum::<f32>() * px }

/// Greedy word wrap like the browser's `white-space: normal`: breaks at spaces and after a hyphen, a word wider than `avail` keeps its own
/// line (no mid-word break). Explicit `\n` starts a new paragraph. Returns the lines.
pub fn wrap(text: &str, px: f32, avail: f32) -> Vec<String> {
    let mut out = Vec::new();
    for para in text.split('\n') {
        let mut cur = String::new();
        for word in para.split(' ').filter(|w| !w.is_empty()) {
            // a hyphenated word may break after each hyphen
            let mut pieces: Vec<&str> = Vec::new();
            let mut start = 0;
            for (i, c) in word.char_indices() { if c == '-' && i + 1 < word.len() { pieces.push(&word[start..=i]); start = i + 1; } }
            pieces.push(&word[start..]);
            for (n, piece) in pieces.iter().enumerate() {
                let glue = if n == 0 && !cur.is_empty() { " " } else { "" };
                if !cur.is_empty() && text_width(&format!("{cur}{glue}{piece}"), px) > avail {
                    out.push(std::mem::take(&mut cur));
                    cur.push_str(piece);
                } else { cur.push_str(glue); cur.push_str(piece); }
            }
        }
        out.push(cur);
    }
    if out.len() == 1 && out[0].is_empty() { out.clear(); }
    out
}

pub fn line_count(text: &str, px: f32, avail: f32) -> usize { wrap(text, px, avail).len() }
/// `text` with the line breaks of [`wrap`] written as `\n`.
pub fn wrapped(text: &str, px: f32, avail: f32) -> String { wrap(text, px, avail).join("\n") }

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn widths_match_measured_stock_lines() {
        // (text, px, ink width measured on the 1280x800 stock captures); advance is ~3 px wider than ink
        for (t, px, ink) in [("Завершать скачивание с выключенным экраном перед", 24., 696.), ("Процент заряда батареи", 24., 314.),
            ("Показывать вверху процент заряд батареи", 18., 411.), ("Выключать телевизор при переходе в спящий режим", 24., 677.),
            ("Если ваше устройство перейдёт в спящее состояние, скачивание игр", 18., 661.)] {
            let w = text_width(t, px);
            assert!(w >= ink && w - ink <= 9., "{t}: {w} vs {ink}");
        }
    }
    #[test]
    fn wraps_like_a_browser() {
        assert_eq!(wrap("", 24., 100.), Vec::<String>::new());
        assert_eq!(wrap("aaa bbb", 24., 1000.), ["aaa bbb"]);
        let l = wrap("Выходить из спящего режима при включении телевизора", 24., 710.);
        assert_eq!(l, ["Выходить из спящего режима при включении", "телевизора"]);
        assert_eq!(wrap("a\nb", 24., 1000.), ["a", "b"]); // explicit break
        assert_eq!(wrap("supercalifragilistic", 24., 50.), ["supercalifragilistic"]); // overlong word keeps its line
        assert_eq!(wrap("one-two-three four", 24., text_width("one-two-", 24.) + 1.), ["one-two-", "three", "four"]);
    }
}
